 case WM_ENTERSIZEMOVE:interactiveResize=true;SetTimer(hwnd,4,16,nullptr);return 0;
 case WM_EXITSIZEMOVE:KillTimer(hwnd,4);interactiveResize=false;resizePending=false;resize();return 0;
 case WM_MOVE:case WM_DISPLAYCHANGE:InvalidateRect(hwnd,nullptr,FALSE);break;
